        assert.ok(md.indexOf('| Branch | bug/X-1 |') !== -1);
        assert.ok(md.indexOf('| App Path | `/tmp/app/X.app` |') !== -1);
        assert.ok(md.indexOf('export APP_PATH="/tmp/app/X.app"') !== -1);
